const fs = require('fs');

(function main() {
  const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
  let ti = 0;
  const n = +tokens[ti++];
  const m = +tokens[ti++];
  const size = n + 1; // BIT indices 1..n+1 (n+1 usado para o ponto R+1)

  // FRENTE: f(p) = (V + L) - p para p em [L, R]
  // TRAS:   f(p) = p + (V - i)   para p em [L', i]
  // fc/fsm: contagem e soma de C=(V+L) das atualizações FRENTE que cobrem p
  // tc/tsm: contagem e soma de D=(V-i) das atualizações TRAS que cobrem p
  const fc = new Float64Array(size + 1);
  const fsm = new Float64Array(size + 1);
  const tc = new Float64Array(size + 1);
  const tsm = new Float64Array(size + 1);
  const out = [];

  for (let k = 0; k < m; k++) {
    const type = +tokens[ti++];
    if (type === 3) {
      const p = +tokens[ti++];
      let cf = 0, sf = 0, ct = 0, st = 0;
      for (let i = p; i > 0; i -= i & -i) {
        cf += fc[i]; sf += fsm[i];
        ct += tc[i]; st += tsm[i];
      }
      // resposta = (ΣC - p*cntF) + (p*cntT + ΣD)
      out.push(String(Math.round(sf - p * cf + p * ct + st)));
    } else if (type === 1) {
      const i0 = +tokens[ti++];
      const v = +tokens[ti++];
      const C = v + i0;
      for (let j = i0; j <= size; j += j & -j) { fc[j] += 1; fsm[j] += C; }
      const r1 = i0 + v <= n + 1 ? i0 + v : n + 1; // R + 1, R = min(n, i0+v-1)
      for (let j = r1; j <= size; j += j & -j) { fc[j] -= 1; fsm[j] -= C; }
    } else {
      const i0 = +tokens[ti++];
      const v = +tokens[ti++];
      const D = v - i0;
      const l1 = i0 - v + 1 > 1 ? i0 - v + 1 : 1; // L' = max(1, i0-v+1)
      for (let j = l1; j <= size; j += j & -j) { tc[j] += 1; tsm[j] += D; }
      for (let j = i0 + 1; j <= size; j += j & -j) { tc[j] -= 1; tsm[j] -= D; }
    }
  }
  process.stdout.write(out.join('\n') + '\n');
})();
